CREATE TABLE dictionary_definitions (id text PRIMARY KEY,dictionary_code text NOT NULL,name text NOT NULL,dictionary_type text NOT NULL CHECK(dictionary_type IN('enum','tree')),source_type text NOT NULL CHECK(source_type IN('static','provider')),description text NOT NULL DEFAULT '',status text NOT NULL CHECK(status IN('active','disabled')),extension jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(extension)='object'),created_at timestamptz NOT NULL,created_by text NOT NULL,updated_at timestamptz NOT NULL,updated_by text NOT NULL,version bigint NOT NULL CHECK(version>0),deleted_at timestamptz,deleted_by text);
CREATE UNIQUE INDEX dictionary_definitions_code_unique ON dictionary_definitions(lower(dictionary_code)) WHERE deleted_at IS NULL;
SELECT app_enable_audit('dictionary_definitions');
CREATE TABLE dictionary_items (id text PRIMARY KEY,dictionary_id text NOT NULL REFERENCES dictionary_definitions(id),parent_id text,code text NOT NULL,name text NOT NULL,value text NOT NULL DEFAULT '',disabled boolean NOT NULL DEFAULT false,sort_order bigint NOT NULL DEFAULT 0,extension jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(extension)='object'),created_at timestamptz NOT NULL,created_by text NOT NULL,updated_at timestamptz NOT NULL,updated_by text NOT NULL,version bigint NOT NULL CHECK(version>0),deleted_at timestamptz,deleted_by text,UNIQUE(id,dictionary_id),FOREIGN KEY(parent_id,dictionary_id) REFERENCES dictionary_items(id,dictionary_id));
CREATE UNIQUE INDEX dictionary_items_code_unique ON dictionary_items(dictionary_id,lower(code)) WHERE deleted_at IS NULL;
CREATE INDEX dictionary_items_query_idx ON dictionary_items(dictionary_id,disabled,sort_order) WHERE deleted_at IS NULL;
CREATE INDEX dictionary_items_parent_idx ON dictionary_items(dictionary_id,parent_id) WHERE deleted_at IS NULL;
SELECT app_enable_audit('dictionary_items');
